texts.9a7ad1237322d835a1a5fbdb65bd2a500d294392:
"""MiniAgent workspace tool: execute code in the official AppWorld shell.

The AppWorld shell is persistent: variables survive across tool calls. This
tool executes each top-level statement of the submitted cell as its own shell
operation, then recombines the results. Executing statements separately means
one large early `print` cannot consume the whole output budget and hide later,
more task-relevant output.

Bare expression statements (for example a call to
`apis.supervisor.show_active_task()` without an explicit `print`) are evaluated
once and their return value is printed automatically. This keeps useful API
return values visible without asking the model to re-run calls with `print`.
A bare login/authenticate call is the exception: its result is stored in
`_appworld_login_result` and only a short confirmation is printed, so the raw
access token does not bloat or truncate the tool result.

The response is deliberately compact. It starts and ends with a machine-readable
`[appworld meta: ...]` line so truncation and completion state remain visible
even when an upstream transport cuts the middle of the payload.
"""

import ast
import asyncio
import json
import re

# Keep tool output bounded for the LLM. AppWorld API-doc calls can return very
# large payloads, and unbounded output consumes the model's context before any
# task-relevant call is made.
_OUTPUT_LIMIT_CHARS = 16 * 1024
_STREAM_LIMIT_BYTES = 8 * 1024 * 1024

_TRUNCATION_NOTE = (
    "[appworld: output truncated to {limit} characters; "
    "{omitted} characters omitted. Re-run with a narrower query, "
    "`recursive=False`, a substring/entry_type filter, or pagination "
    "to inspect the omitted output.]"
)
_EARLIER_OMITTED_NOTE = (
    "[appworld: {count} earlier statement output(s) omitted so the first and "
    "last statements stay visible under the {limit}-character total output cap. "
    "Re-run those statements individually if their output is needed.]\n"
)


def _stringify(value) -> str:
    if isinstance(value, str):
        return value
    try:
        return json.dumps(value, ensure_ascii=False)
    except Exception:
        return str(value)


def _first_present(mapping: dict, keys) -> object:
    for key in keys:
        if key in mapping and mapping[key] is not None:
            return mapping[key]
    return None


def _truncate(text: str, limit: int) -> str:
    if len(text) <= limit:
        return text
    omitted = len(text) - limit
    note = _TRUNCATION_NOTE.format(limit=limit, omitted=omitted)
    # Put the marker on both sides of the retained content. A transport that
    # cuts the tail still leaves the leading marker visible to the model.
    return note + "\n" + text[:limit] + "\n" + note


def _looks_truncated(chunk: str) -> bool:
    return (
        "[appworld: output truncated" in chunk
        or "earlier statement output(s) omitted" in chunk
    )


def _module_hint(text: str) -> str:
    """Turn opaque sandbox import denials into an actionable next step."""
    if "Usage of the following module is not allowed: apis" in text:
        return (
            "\n[appworld hint] `apis` is already injected as a global in this shell. "
            "Remove `import apis` and call it directly, e.g. "
            "`apis.api_docs.show_app_descriptions()`."
        )
    if "Usage of the following modules is not allowed: importlib and sys" in text:
        return (
            "\n[appworld hint] `import sys`/`importlib` are blocked in this shell. "
            "Use the pre-injected `apis` and `requester` globals instead."
        )
    if "module is not allowed" in text:
        return (
            "\n[appworld hint] That import is blocked in this shell. "
            "Use the pre-injected `apis`/`requester` globals instead of importing modules."
        )
    return ""


def _format_chunk(raw: str, limit: int) -> str:
    """Format one shell operation's response without the terminal marker."""
    try:
        data = json.loads(raw)
    except json.JSONDecodeError:
        return _truncate(raw, limit) if raw else "(no output)"

    if isinstance(data, str):
        return _truncate(data, limit) if data else "(no output)"

    if isinstance(data, dict):
        output = _first_present(data, ("output", "stdout", "result"))
        error = _first_present(data, ("error", "traceback", "exception", "stderr"))

        parts: list[str] = []
        if output is not None:
            parts.append(_stringify(output).rstrip())
        if error is not None:
            err_text = _stringify(error).strip()
            if err_text:
                parts.append(err_text)
        full_text = "\n".join(parts) if parts else _stringify(data)

        hint = _module_hint(full_text)
        text = _truncate(full_text, limit)
        if hint:
            text += hint
        return text

    return _truncate(_stringify(data), limit)


def _task_completed(raw: str):
    try:
        data = json.loads(raw)
    except json.JSONDecodeError:
        return None
    if isinstance(data, dict) and "task_completed" in data:
        return data.get("task_completed")
    return None


def _split_statements(code: str) -> list[str]:
    """Split a code cell into top-level statements.

    Falls back to the original cell for unparseable or empty modules, which
    preserves the previous single-execution behaviour.
    """
    try:
        tree = ast.parse(code)
    except (SyntaxError, ValueError):
        return [code]

    if not tree.body:
        return [code]

    try:
        statements = [ast.get_source_segment(code, node) for node in tree.body]
        if any(statement is None for statement in statements):
            raise ValueError("source segment unavailable")
    except Exception:
        statements = [ast.unparse(node) for node in tree.body]

    statements = [statement for statement in statements if statement and statement.strip()]
    return statements or [code]


def _statement_limit(n_statements: int) -> int:
    """Give each statement a fair share of the total output budget."""
    if n_statements <= 1:
        return _OUTPUT_LIMIT_CHARS
    return max(4 * 1024, _OUTPUT_LIMIT_CHARS // n_statements)


def _compose(chunks: list[str]) -> str:
    if len(chunks) == 1:
        return chunks[0]

    pieces = [
        f"[appworld output {i}/{len(chunks)}]\n{chunk}"
        for i, chunk in enumerate(chunks, 1)
    ]
    omitted = 0
    # Keep the first statement (usually task discovery) and the last statement
    # (usually the completion/verification call). Drop from the middle first so
    # a bulky doc-print in the middle cannot hide the terminal state.
    while (
        len(pieces) > 2
        and sum(len(piece) + 2 for piece in pieces) > _OUTPUT_LIMIT_CHARS
    ):
        pieces.pop(1)
        omitted += 1

    text = "\n\n".join(pieces)
    if omitted:
        text = _EARLIER_OMITTED_NOTE.format(
            count=omitted, limit=_OUTPUT_LIMIT_CHARS
        ) + text
    return text


def _should_autoprint(statement: str) -> bool:
    """Return True for a bare expression whose value should be made visible."""
    try:
        tree = ast.parse(statement)
    except (SyntaxError, ValueError):
        return False

    if len(tree.body) != 1 or not isinstance(tree.body[0], ast.Expr):
        return False

    value = tree.body[0].value
    # Constants/docstrings already add no information. A bare `print(...)` call
    # already produces output; re-printing its `None` return is only noise.
    if isinstance(value, (ast.Constant, ast.JoinedStr)):
        return False
    if isinstance(value, ast.Call) and isinstance(value.func, ast.Name):
        if value.func.id == "print":
            return False

    return True


def _bare_auth_call_expression(statement: str) -> str | None:
    """Return the source expression for a bare login/authenticate call.

    Login responses contain an access token. Auto-printing them truncates or
    bloats the tool result, and the model can use the stored result without
    ever seeing the raw token. We detect these calls before the generic
    autoprint path and store their result in a documented shell variable
    instead.
    """
    try:
        tree = ast.parse(statement)
    except (SyntaxError, ValueError):
        return None

    if len(tree.body) != 1 or not isinstance(tree.body[0], ast.Expr):
        return None

    value = tree.body[0].value
    if not isinstance(value, ast.Call):
        return None

    func = value.func
    if isinstance(func, ast.Name):
        name = func.id
    elif isinstance(func, ast.Attribute):
        name = func.attr
    else:
        return None

    if name not in {"login", "log_in", "authenticate"}:
        return None

    return ast.get_source_segment(statement, value) or ast.unparse(value)


def _prepare_statement(statement: str) -> str:
    """Evaluate a bare expression once and print its return value."""
    auth_expr = _bare_auth_call_expression(statement)
    if auth_expr:
        return (
            "_appworld_login_result = " + auth_expr + "\n"
            "print('[appworld: login result stored in `_appworld_login_result`. "
            "`login()` usually returns an object with an `access_token` field; "
            "pass `_appworld_login_result[\"access_token\"]` to authenticated "
            "calls. Do not print the raw login result.]')"
        )
    if not _should_autoprint(statement):
        return statement
    return f"print({statement})"


async def _execute_once(endpoint: str, code: str) -> str:
    reader, writer = await asyncio.open_unix_connection(
        endpoint, limit=_STREAM_LIMIT_BYTES
    )
    try:
        payload = json.dumps({"operation": "execute", "code": code}) + "\n"
        writer.write(payload.encode())
        await writer.drain()
        return (await reader.readline()).decode("utf-8", errors="replace").strip()
    finally:
        writer.close()
        await writer.wait_closed()


async def call(args, ctx):
    code = args.get("code")
    if not isinstance(code, str) or not code.strip():
        raise ValueError("code must be a non-empty string")

    endpoint = json.loads(
        (ctx.working_dir / "appworld-connection.json").read_text()
    )["socket"]

    statements = _split_statements(code)
    limit = _statement_limit(len(statements))

    chunks: list[str] = []
    final_task_completed = None
    truncated_any = False
    complete_task_called = False
    for statement in statements:
        if re.search(r"\bcomplete_task\s*\(", statement):
            complete_task_called = True
        prepared = _prepare_statement(statement)
        raw = await _execute_once(endpoint, prepared)
        chunk = _format_chunk(raw, limit)
        truncated_any = truncated_any or _looks_truncated(chunk)
        chunks.append(chunk)
        task_completed = _task_completed(raw)
        if task_completed is not None:
            final_task_completed = task_completed

    text = _compose(chunks)
    truncated_any = truncated_any or _looks_truncated(text)

    meta = {
        "n_statements": len(statements),
        "truncated": truncated_any,
        "task_completed": final_task_completed,
        "complete_task_called": complete_task_called,
    }
    meta_line = f"[appworld meta: {json.dumps(meta, ensure_ascii=False)}]"
    if final_task_completed is not None:
        text += f"\n[appworld task_completed: {json.dumps(final_task_completed)}]"

    # Emit meta at both the start and the end. If an upstream capture cuts the
    # tail, the leading meta line still records truncation/completion state.
    return meta_line + "\n" + text + "\n" + meta_line

texts.c4f0f00d7cdf3f665fb4877f6922ac26a7b5314a:
"""AppWorld execution guard.

AppWorld tasks are graded on world state and must be finished from inside
`appworld_execute` with `apis.supervisor.complete_task(...)`. This middleware
turns the observed failure modes into recoverable feedback instead of silent
task failure:

* broad API-doc/list dumps that exhaust the output budget before task work
* long read-only discovery with no state-changing call
* a final text answer emitted without a successful `complete_task`
* login results passed whole as `access_token`, producing deterministic 401s

The classification is intentionally shallow and general: it inspects the code
cell for API calls (by name), counts read-like vs write-like calls, tracks
repeated reads rather than punishing every legitimate discovery step, and
parses the harness-visible `[appworld task_completed: ...]` marker. It never
encodes specific AppWorld applications or task answers.
"""

from __future__ import annotations

import ast
import re
from typing import Any

_READ_ONLY_PREFIXES = (
    "show",
    "search",
    "list",
    "get",
    "find",
    "describe",
    "display",
    "fetch",
    "read",
)
_AUTH_NAMES = {"login", "log_in", "logout", "log_out", "authenticate"}
_COMPLETE_NAME = "complete_task"
_API_PATH_MARKERS = ("apis", "supervisor", "requester")
# Broad API documentation calls. `show_app_descriptions()` is intentionally
# excluded: the task prompt directs the model to call it, and it returns only
# app names/descriptions.
_DOC_API_NAMES = {"show_api_doc", "show_api_descriptions"}
# Task-discovery calls are setup, not data reads. They never count toward the
# read-only discovery budget.
_TASK_DISCOVERY_NAMES = {"show_active_task", "show_app_descriptions"}
_MAX_DOC_CALLS_PER_CELL = 2

# Repeated identical reads are the strongest no-progress signal. Only after the
# same read call has been issued this many times (or after a large number of
# distinct data reads) do we ask the model to stop reading and move to writes.
_DUP_READ_NUDGE_AT = 3
_MANY_READS_NUDGE_AT = 12
_BUDGET_NUDGE_TURNS_LEFT = 2


def _call_node_name(node: ast.Call) -> str | None:
    func = node.func
    if isinstance(func, ast.Name):
        return func.id
    if isinstance(func, ast.Attribute):
        return func.attr
    return None


def _is_api_call(node: ast.Call) -> bool:
    """True when `node` is an AppWorld-client call, not a plain Python call."""
    func = node.func
    if isinstance(func, ast.Name):
        full = func.id
    elif isinstance(func, ast.Attribute):
        try:
            full = ast.unparse(func)
        except Exception:
            return False
    else:
        return False
    return any(marker in full for marker in _API_PATH_MARKERS)


def _api_call_signatures(code: str) -> list[tuple[str, str]]:
    """Return (name, signature) for AppWorld-API-looking calls in `code`."""
    try:
        tree = ast.parse(code)
    except (SyntaxError, ValueError):
        return []

    calls: list[tuple[str, str]] = []
    for node in ast.walk(tree):
        if not isinstance(node, ast.Call):
            continue
        if not _is_api_call(node):
            continue
        name = _call_node_name(node)
        if not name:
            continue
        parts: list[str] = []
        for arg in node.args:
            try:
                parts.append(ast.unparse(arg))
            except Exception:
                parts.append("?")
        for kw in node.keywords:
            try:
                parts.append(f"{kw.arg}={ast.unparse(kw.value)}")
            except Exception:
                parts.append(f"{kw.arg}=?")
        calls.append((name, f"{name}({', '.join(parts)})"))
    return calls


def _api_call_names(code: str) -> list[str]:
    return [name for name, _ in _api_call_signatures(code)]


def _split_statements(code: str) -> list[str]:
    """Split a code cell into top-level statements for doc-limit rewriting."""
    try:
        tree = ast.parse(code)
    except (SyntaxError, ValueError):
        return [code]

    if not tree.body:
        return [code]

    try:
        statements = [ast.get_source_segment(code, node) for node in tree.body]
        if any(statement is None for statement in statements):
            raise ValueError("source segment unavailable")
    except Exception:
        statements = [ast.unparse(node) for node in tree.body]

    statements = [statement for statement in statements if statement and statement.strip()]
    return statements or [code]


def _statement_is_doc_loop(statement: str) -> bool:
    """True when a top-level loop body contains an AppWorld API-doc call."""
    try:
        tree = ast.parse(statement)
    except (SyntaxError, ValueError):
        return False

    for node in ast.walk(tree):
        if not isinstance(node, (ast.For, ast.While)):
            continue
        for sub in ast.walk(node):
            if isinstance(sub, ast.Call) and _call_node_name(sub) in _DOC_API_NAMES:
                return True
    return False


def _rewrite_doc_cell(code: str) -> str | None:
    """Return a non-destructive version of `code` that keeps at most two doc calls.

    Instead of discarding the whole cell when it batches too many API-doc calls
    (or loops over doc calls), keep the first two doc statements and replace the
    excess with a short printed note. Non-doc statements are always kept, so a
    login/credential call in the same cell still executes.
    """
    statements = _split_statements(code)
    kept: list[str] = []
    changed = False
    doc_kept = 0
    skip_note = (
        "print('[appworld guard] Skipped documentation call(s) in this cell to keep "
        "the output bounded. Run at most "
        f"{_MAX_DOC_CALLS_PER_CELL} narrow `show_api_doc`/`show_api_descriptions` "
        "calls per cell, one at a time, and print only the fields you need.')"
    )

    for statement in statements:
        doc_count = sum(1 for n in _api_call_names(statement) if n in _DOC_API_NAMES)
        is_doc_loop = _statement_is_doc_loop(statement)

        if (
            is_doc_loop
            or doc_count > _MAX_DOC_CALLS_PER_CELL
            or (doc_count > 0 and doc_kept >= _MAX_DOC_CALLS_PER_CELL)
        ):
            kept.append(skip_note)
            changed = True
            continue

        if doc_count > 0:
            doc_kept += doc_count
        kept.append(statement)

    if not changed:
        return None
    return "\n".join(kept)


def _classify(name: str) -> str:
    if name == _COMPLETE_NAME:
        return "complete"
    if name in _AUTH_NAMES:
        return "auth"
    if name in _DOC_API_NAMES:
        return "doc"
    if name in _TASK_DISCOVERY_NAMES:
        return "meta"
    if name.startswith(_READ_ONLY_PREFIXES):
        return "read"
    return "write"


def _login_assignments(code: str) -> list[str]:
    """Return variable names assigned from an AppWorld login/authenticate call."""
    try:
        tree = ast.parse(code)
    except (SyntaxError, ValueError):
        return []

    names: list[str] = []
    for node in ast.walk(tree):
        if not isinstance(node, (ast.Assign, ast.AnnAssign)):
            continue
        value = node.value
        if not isinstance(value, ast.Call):
            continue
        if not _is_api_call(value) or _call_node_name(value) not in _AUTH_NAMES:
            continue
        targets = node.targets if isinstance(node, ast.Assign) else [node.target]
        for target in targets:
            if isinstance(target, ast.Name):
                names.append(target.id)
    return names


def _access_token_vars(code: str) -> list[str]:
    """Return variable names passed as `access_token=` in API-looking calls."""
    try:
        tree = ast.parse(code)
    except (SyntaxError, ValueError):
        return []

    names: list[str] = []
    for node in ast.walk(tree):
        if not isinstance(node, ast.Call):
            continue
        if not _is_api_call(node):
            continue
        for kw in node.keywords:
            if kw.arg == "access_token" and isinstance(kw.value, ast.Name):
                names.append(kw.value.id)
    return names


def _task_completed_true(result: Any) -> bool:
    if not isinstance(result, str):
        return False
    return bool(re.search(r"\[appworld task_completed: true\]", result))


def _guard_state(ctx) -> dict:
    return ctx.state.setdefault(
        "appworld_guard",
        {
            "read_ops": 0,
            "auth_ops": 0,
            "write_ops": 0,
            "complete_attempts": 0,
            "complete_task_called": False,
            "completed": False,
            "doc_calls": 0,
            "doc_dump_nudged": False,
            "read_signatures": {},
            "dup_nudged_sigs": [],
            "many_reads_nudged": False,
            "login_vars": [],
            "plan_nudge_reason": None,
            "last_plan_nudge_turn": 0,
            "last_budget_nudge_turn": 0,
        },
    )


async def before_tool(name: str, args: dict, ctx) -> Any:
    """Rewrites (not discard) cells that batch too many API-doc calls."""
    if name != "appworld_execute":
        return None

    code = args.get("code") or ""
    if not isinstance(code, str) or not code.strip():
        return None

    new_code = _rewrite_doc_cell(code)
    if new_code is None or new_code == code:
        return None

    new_args = dict(args)
    new_args["code"] = new_code
    return (name, new_args)


async def after_tool(name: str, args: dict, result: str, ctx) -> Any:
    if name != "appworld_execute":
        return None

    guard = _guard_state(ctx)
    code = args.get("code") or ""
    if not isinstance(code, str):
        code = ""

    api_calls = _api_call_signatures(code)
    has_write = False
    has_complete = False
    has_auth = False
    read_signatures_seen: list[str] = []

    for login_var in _login_assignments(code):
        if login_var not in guard.get("login_vars", []):
            guard["login_vars"].append(login_var)

    for call_name, signature in api_calls:
        kind = _classify(call_name)
        if kind == "complete":
            guard["complete_attempts"] += 1
            guard["complete_task_called"] = True
            has_complete = True
        elif kind == "write":
            guard["write_ops"] += 1
            has_write = True
        elif kind == "auth":
            guard["auth_ops"] += 1
            has_auth = True
        elif kind == "doc":
            guard["doc_calls"] = guard.get("doc_calls", 0) + 1
        elif kind == "read":
            guard["read_ops"] += 1
            read_signatures_seen.append(signature)
        # "meta" calls (task discovery / app descriptions) are setup and are
        # intentionally not counted as reads.

    if read_signatures_seen:
        read_signatures = guard.setdefault("read_signatures", {})
        for signature in read_signatures_seen:
            read_signatures[signature] = read_signatures.get(signature, 0) + 1

    if _task_completed_true(result):
        guard["completed"] = True

    if guard["completed"]:
        return None

    nudges: list[str] = []

    # Documentation calls are useful but context-hungry. Warn once, and only
    # when no write has happened yet, so a narrow doc lookup is still allowed.
    if (
        guard["write_ops"] == 0
        and guard.get("doc_calls", 0) > 0
        and not guard.get("doc_dump_nudged")
    ):
        guard["doc_dump_nudged"] = True
        nudges.append(
            "[appworld guard] API documentation output is size-capped and consumes "
            "context. Use the narrowest `show_api_doc`/`show_api_descriptions` call "
            "and print only the fields needed for the task, then move on to the "
            "actual task calls."
        )

    # Detect repeated identical reads (no-progress loops) instead of punishing
    # every distinct discovery read. This still catches doc/list loops without
    # freezing legitimate entity resolution.
    if guard["write_ops"] == 0 and guard.get("read_ops", 0) > 0:
        read_signatures = guard.setdefault("read_signatures", {})
        dup_nudged = guard.setdefault("dup_nudged_sigs", [])
        for signature in read_signatures_seen:
            count = read_signatures.get(signature, 0)
            if count >= _DUP_READ_NUDGE_AT and signature not in dup_nudged:
                dup_nudged.append(signature)
                guard["plan_nudge_reason"] = (
                    f"repeated read-only call {signature} ({count} times)"
                )
                nudges.append(
                    "[appworld guard] The same read-only AppWorld call has now been "
                    f"issued {count} times with no state-changing call. Stop re-reading "
                    "that endpoint. In your next `appworld_execute` cell, print the "
                    "concrete entities and values you resolved, then perform the exact "
                    "state-changing calls the task requires (or call "
                    "`apis.supervisor.complete_task(...)` if the required state "
                    "already exists)."
                )

        if (
            len(read_signatures) >= _MANY_READS_NUDGE_AT
            and not guard.get("many_reads_nudged")
        ):
            guard["many_reads_nudged"] = True
            guard["plan_nudge_reason"] = (
                f"{len(read_signatures)} distinct read-only calls with no write"
            )
            nudges.append(
                "[appworld guard] This rollout has made "
                f"{len(read_signatures)} distinct read-only AppWorld API calls and no "
                "state-changing call. If the task requires writes, stop reading, state "
                "the concrete entities you resolved and the exact write calls you will "
                "make, then perform those writes now. If the required world state "
                "already exists, call `apis.supervisor.complete_task(...)` inside "
                "`appworld_execute` now."
            )

    # Local auth-argument validation. A 401 that occurs after a login result
    # was passed directly as `access_token` is almost always a shape mismatch:
    # `login()` returns an object with an `access_token` field, not the bare
    # token string.
    result_lower = (result or "").lower()
    if (
        "401" in result_lower
        or "missing, invalid or expired" in result_lower
        or "not authorized" in result_lower
    ):
        token_vars = set(_access_token_vars(code))
        bad_vars = sorted(token_vars.intersection(guard.get("login_vars", [])))
        if bad_vars:
            example = bad_vars[0]
            nudges.append(
                "[appworld guard] The authentication error means the value passed as "
                "`access_token` was not accepted. `login()` normally returns a "
                "structured object such as `{\"access_token\": \"...\", \"token_type\": "
                "\"...\"}`. Pass only the token string, for example "
                f"`{example}[\"access_token\"]`, not the whole login result. If this "
                "app's login doc shows a different shape, follow that doc; if it "
                "returns a bare string, pass that string directly."
            )

    # Near the turn budget, be explicit that the run will otherwise fail.
    if ctx.remaining_turns <= _BUDGET_NUDGE_TURNS_LEFT:
        if guard.get("last_budget_nudge_turn", 0) != ctx.turn:
            guard["last_budget_nudge_turn"] = ctx.turn
            nudges.append(
                f"[appworld guard] Only {ctx.remaining_turns} turn(s) remain. "
                "Do not emit a final text answer: finish inside "
                "`appworld_execute` with `apis.supervisor.complete_task(...)` "
                "after the required world state is produced and verified."
            )

    if not nudges:
        return None

    return {"result": str(result) + "\n" + "\n".join(nudges)}


async def before_llm(messages: list, ctx) -> Any:
    """Inject one write-plan checkpoint after duplicate/no-progress reads.

    This is a softer, top-of-turn reminder than the trailing tool-result note.
    It never says to stop all reads; it only asks the model to stop re-reading
    the same endpoint and move to the required writes/completion.
    """
    guard = _guard_state(ctx)

    if guard.get("completed"):
        return messages
    if guard.get("write_ops", 0) > 0 or guard.get("complete_attempts", 0) > 0:
        return messages

    reason = guard.get("plan_nudge_reason")
    if not reason:
        return messages
    if guard.get("last_plan_nudge_turn", 0) == ctx.turn:
        return messages

    guard["last_plan_nudge_turn"] = ctx.turn
    guard["plan_nudge_reason"] = None
    nudge = (
        "[appworld guard] You have made repeated or many read-only AppWorld API "
        f"calls and no state-changing call ({reason}). Avoid re-reading the same "
        "endpoints. In your next `appworld_execute` cell, print the concrete "
        "entities and values you resolved, then perform the exact state-changing "
        "calls the task requires, or call `apis.supervisor.complete_task(...)` if "
        "the required state already exists."
    )
    return messages + [{"role": "user", "content": nudge}]


async def before_final(answer: str, ctx) -> Any:
    """Block text-only final answers until complete_task reports success."""
    guard = _guard_state(ctx)

    if guard.get("completed"):
        return None

    if not answer.strip():
        feedback = (
            "You produced no visible text and no tool call. AppWorld tasks are "
            "finished from inside `appworld_execute`: verify the required world "
            "state, then call `apis.supervisor.complete_task(...)` (with a "
            "concise `answer` only if the task is a question). Issue that "
            "`appworld_execute` call now."
        )
    else:
        if guard.get("write_ops", 0) == 0:
            write_note = (
                "This rollout has not made a state-changing AppWorld call yet. "
                "If this is an action task, perform the required writes first; "
                "if it is a question task, ignore this note. "
            )
        else:
            write_note = ""
        feedback = (
            "Do not return a final text answer for an AppWorld task; the grader "
            "checks the produced world state and whether "
            "`apis.supervisor.complete_task(...)` was called inside "
            "`appworld_execute`. "
            + write_note
            + "If the required state is already produced, call "
            "`apis.supervisor.complete_task(...)` now (with a concise `answer` "
            "only if the task is a question)."
        )

    return {"action": "continue", "feedback": feedback}

